import sys

def parse_price(price_str):
    parts = price_str.split('.')
    if len(parts) == 1:
        return int(parts[0]), 0
    elif len(parts) == 2:
        dollars = int(parts[0].replace('.', ''))
        cents = int(parts[1])
        return dollars, cents
    else:
        raise ValueError("Invalid price format")

def format_price(dollars, cents):
    if cents == 0:
        return f"{dollars:,}"
    else:
        return f"{dollars:,}.{cents:02}"

s = sys.stdin.read().strip()
total_dollars = 0
total_cents = 0
current_number = ''

for char in s:
    if char.isdigit() or char == '.':
        current_number += char
    else:
        if current_number:
            dollars, cents = parse_price(current_number)
            total_dollars += dollars
            total_cents += cents
            if total_cents >= 100:
